 dep=Path(q['post_prepared_directory']);build=Path(q['build_directory']);pm=artifacts(dep);bm=artifacts(build);need(pm['status']=='EXACT_POSTPHYSICAL97_GATE_EXPORT'and q['post_prepared_manifest_sha256']==sha(dep/'manifest.json')and pm['admission']==admission and pm['original_prepared_manifest_sha256']==sha(prepared/'manifest.json')and pm['physical_stage_manifest_sha256']==sha(physical/'manifest.json')and pm['physical_final_verilog_sha256']==sha(physical/'final.v'),'actual97 postgate prepared netlist');need(bm['status']=='POSTPHYSICAL97_GATE_BUILT_NOT_EXECUTED'and q['build_manifest_sha256']==sha(build/'manifest.json')and bm['prepared_manifest_sha256']==sha(dep/'manifest.json')and bm['admission']==admission and bm['original_prepared_manifest_sha256']==sha(prepared/'manifest.json')and sha(build/'obj/Vchain97')==bm['binary_sha256'],'exact97 binary')
